import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    private static class Frame {
        TreeNode node;
        long lower;
        long upper;

        Frame(TreeNode node, long lower, long upper) {
            this.node = node;
            this.lower = lower;
            this.upper = upper;
        }
    }

    public boolean isValidBST(TreeNode root) {
        Deque<Frame> stack = new ArrayDeque<>();
        stack.push(new Frame(root, Long.MIN_VALUE, Long.MAX_VALUE));
        while (!stack.isEmpty()) {
            Frame frame = stack.pop();
            long value = frame.node.val;
            if (value <= frame.lower || value >= frame.upper) return false;
            if (frame.node.right != null) {
                stack.push(new Frame(frame.node.right, value, frame.upper));
            }
            if (frame.node.left != null) {
                stack.push(new Frame(frame.node.left, frame.lower, value));
            }
        }
        return true;
    }
}
